809	static void draw_main(lv_event_t * e)
810	{
811	    lv_obj_t * obj = lv_event_get_current_target(e);
812	    lv_label_t * label = (lv_label_t *)obj;
813	    lv_layer_t * layer = lv_event_get_layer(e);
814	
815	    lv_area_t txt_coords;
816	    lv_obj_get_content_coords(obj, &txt_coords);
817	
818	    lv_text_flag_t flag = get_label_flags(label);
819	
820	    lv_draw_label_dsc_t label_draw_dsc;
821	    lv_draw_label_dsc_init(&label_draw_dsc);
822	    label_draw_dsc.text = label->text;
823	    label_draw_dsc.text_static = label->static_txt;
824	    label_draw_dsc.ofs_x = label->offset.x;
825	    label_draw_dsc.ofs_y = label->offset.y;
826	    label_draw_dsc.text_size = label->text_size;
827	#if LV_LABEL_LONG_TXT_HINT
828	    if(label->long_mode != LV_LABEL_LONG_MODE_SCROLL_CIRCULAR &&
829	       lv_area_get_height(&txt_coords) >= LV_LABEL_HINT_HEIGHT_LIMIT) {
830	        label_draw_dsc.hint = &label->hint;
831	    }
832	#endif
833	
834	    label_draw_dsc.flag = flag;
835	    label_draw_dsc.base.layer = layer;
836	    lv_obj_init_draw_label_dsc(obj, LV_PART_MAIN, &label_draw_dsc);
837	    lv_bidi_calculate_align(&label_draw_dsc.align, &label_draw_dsc.bidi_dir, label->text);
838	
839	    label_draw_dsc.sel_start = lv_label_get_text_selection_start(obj);
840	    label_draw_dsc.sel_end = lv_label_get_text_selection_end(obj);
841	    if(label_draw_dsc.sel_start != LV_DRAW_LABEL_NO_TXT_SEL && label_draw_dsc.sel_end != LV_DRAW_LABEL_NO_TXT_SEL) {
842	        label_draw_dsc.sel_color = lv_obj_get_style_text_color_filtered(obj, LV_PART_SELECTED);
843	        label_draw_dsc.sel_bg_color = lv_obj_get_style_bg_color(obj, LV_PART_SELECTED);
844	    }
845	
846	    /* get the style attributes of a letter outline */
847	    label_draw_dsc.outline_stroke_color = lv_obj_get_style_text_outline_stroke_color(obj, LV_PART_MAIN);
848	    label_draw_dsc.outline_stroke_opa = lv_obj_get_style_text_outline_stroke_opa(obj, LV_PART_MAIN);
849	    label_draw_dsc.outline_stroke_width = lv_obj_get_style_text_outline_stroke_width(obj, LV_PART_MAIN);
850	
851	
852	    /* In SCROLL and SCROLL_CIRCULAR mode the CENTER and RIGHT are pointless, so remove them.
853	     * (In addition, they will create misalignment in this situation)*/
854	    if((label->long_mode == LV_LABEL_LONG_MODE_SCROLL || label->long_mode == LV_LABEL_LONG_MODE_SCROLL_CIRCULAR) &&
855	       (label_draw_dsc.align == LV_TEXT_ALIGN_CENTER || label_draw_dsc.align == LV_TEXT_ALIGN_RIGHT)) {
856	        lv_point_t size = label->text_size;
857	        if(size.x > lv_area_get_width(&txt_coords)) {
858	#if LV_USE_BIDI
859	            const lv_base_dir_t base_dir = lv_obj_get_style_base_dir(obj, LV_PART_MAIN);
860	            label_draw_dsc.align = base_dir == LV_BASE_DIR_RTL ? LV_TEXT_ALIGN_RIGHT : LV_TEXT_ALIGN_LEFT;
861	#else
862	            label_draw_dsc.align = LV_TEXT_ALIGN_LEFT;
863	#endif
864	        }
865	    }
866	
867	    lv_area_t txt_clip;
868	    bool is_common = lv_area_intersect(&txt_clip, &txt_coords, &layer->_clip_area);
869	    if(!is_common) {
870	        return;
871	    }
872	
873	    if(label->long_mode == LV_LABEL_LONG_MODE_WRAP) {
874	        int32_t s = lv_obj_get_scroll_top(obj);
875	        lv_area_move(&txt_coords, 0, -s);
876	        txt_coords.y2 = obj->coords.y2;
877	    }
878	    if(label->long_mode == LV_LABEL_LONG_MODE_SCROLL ||
879	       label->long_mode == LV_LABEL_LONG_MODE_SCROLL_CIRCULAR ||
880	       label->long_mode == LV_LABEL_LONG_MODE_CLIP) {
881	        const lv_area_t clip_area_ori = layer->_clip_area;
882	        layer->_clip_area = txt_clip;
883	        lv_draw_label(layer, &label_draw_dsc, &txt_coords);
884	        layer->_clip_area = clip_area_ori;
885	    }
886	    else {
887	        lv_draw_label(layer, &label_draw_dsc, &txt_coords);
888	    }
889	
890	    lv_area_t clip_area_ori = layer->_clip_area;
891	    layer->_clip_area = txt_clip;
892	
893	    if(label->long_mode == LV_LABEL_LONG_MODE_SCROLL_CIRCULAR) {
894	        lv_point_t size = label->text_size;
895	
896	        /*Draw the text again on label to the original to make a circular effect */
897	        if(size.x > lv_area_get_width(&txt_coords)) {
898	            label_draw_dsc.ofs_x = label->offset.x + size.x +
899	                                   lv_font_get_glyph_width(label_draw_dsc.font, ' ', ' ') * LV_LABEL_WAIT_CHAR_COUNT;
900	            label_draw_dsc.ofs_y = label->offset.y;
901	
902	            lv_draw_label(layer, &label_draw_dsc, &txt_coords);
903	        }
904	
905	        /*Draw the text again below the original to make a circular effect */
906	        if(size.y > lv_area_get_height(&txt_coords)) {
907	            label_draw_dsc.ofs_x = label->offset.x;
908	            label_draw_dsc.ofs_y = label->offset.y + size.y + lv_font_get_line_height(label_draw_dsc.font);
909	
910	            lv_draw_label(layer, &label_draw_dsc, &txt_coords);
911	        }
912	    }
913	
914	    layer->_clip_area = clip_area_ori;
915	}
