917	static void overwrite_anim_property(lv_anim_t * dest, const lv_anim_t * src, lv_label_long_mode_t mode)
918	{
919	    switch(mode) {
920	        case LV_LABEL_LONG_MODE_SCROLL:
921	            /* If the dest animation is already running, overwrite is not allowed */
922	            if(dest->act_time <= 0)
923	                dest->act_time = src->act_time;
924	            dest->repeat_cnt = src->repeat_cnt;
925	            dest->repeat_delay = src->repeat_delay;
926	            dest->completed_cb = src->completed_cb;
927	            dest->reverse_delay = src->reverse_delay;
928	            break;
929	        case LV_LABEL_LONG_MODE_SCROLL_CIRCULAR:
930	            /* If the dest animation is already running, overwrite is not allowed */
931	            if(dest->act_time <= 0)
932	                dest->act_time = src->act_time;
933	            dest->repeat_cnt = src->repeat_cnt;
934	            dest->repeat_delay = src->repeat_delay;
935	            dest->completed_cb = src->completed_cb;
936	            break;
937	        default:
938	            break;
939	    }
940	}
